final class ResearchExecutionTest extends WP_UnitTestCase {
 use PhotoWorkflowFixtureIsolation {tearDown as private restoreFixture;}
 private array $extraFloors=[];private array $policy=[];
 protected function setUp():void {parent::setUp();DigiForge\Core\Activator::activate();ShopAccessFixture::reset();$this->capturePhotoFixtureState();global $wpdb;foreach(['jobs','ai_models','ai_tasks']as $m){$t=DigiForge\Database\Tables::{$m}();$this->extraFloors[$t]=(int)$wpdb->get_var('SELECT COALESCE(MAX(id),0) FROM '.$t);}wp_set_current_user(self::factory()->user->create(['role'=>'administrator']));ShopAccessFixture::authorizeActor(get_current_user_id(),['personalized_pod'],['manage_digiforge_pod','manage_digiforge_research','manage_digiforge_ai']);DigiForge\Core\Settings::protectProduction();$wpdb->query('COMMIT');$wpdb->query('SET autocommit=1');}
 protected function tearDown():void {global $wpdb;foreach(array_reverse($this->extraFloors,true)as $t=>$floor)$wpdb->query('DELETE FROM '.$t.' WHERE id>'.(int)$floor);$this->restoreFixture();}
 private function checked($v):array {self::assertNotWPError($v,is_wp_error($v)?$v->get_error_code():'');self::assertIsArray($v);return $v;}
 private function boot():array {
  self::assertTrue(class_exists(ResearchExecution::class),'A durable research queue/worker is required.');$r=new DigiForge\AI\Repository();$task=$this->checked($r->createTask(['task_key'=>'async-'.wp_generate_uuid4(),'name'=>'Synthetic background research','environment'=>'production','required_capabilities'=>['text_generation','shop2_research_fixture']]));$model=$this->checked($r->createModel(['model_key'=>'async-'.wp_generate_uuid4(),'provider'=>'openai','environment'=>'production','model_class'=>'text','capabilities'=>['text_generation','shop2_research_fixture'],'enabled'=>true]));$this->policy=['shop_key'=>'personalized_pod','currency'=>'USD','budgets'=>['run'=>'0.040000','day'=>'0.100000','month'=>'0.200000'],'stages'=>['research'=>['limit'=>5,'monthly_budget'=>'0.200000','task_binding'=>['task_id'=>(int)$task['id'],'provider_models'=>[(int)$model['id']=>'gpt-5.6-luna']]]]];$this->checked((new ShopAiGovernanceRepository())->savePolicy($this->policy));
  $f=json_decode(file_get_contents(__DIR__.'/../fixtures/research/commercial-research.json'),true);$f['research']['title'].=' '.wp_generate_uuid4();$source=$this->checked((new CommercialResearchRepository())->create($f['research']));$transport=new OfflineResearchTransport(['status'=>'completed','payload'=>$f['response'],'model'=>'gpt-5.6-luna','usage'=>['input_tokens'=>10,'output_tokens'=>5,'total_tokens'=>15]]);$s=new ResearchExecution($transport);$run=['run_id'=>'async-'.wp_generate_uuid4(),'started_at'=>gmdate('Y-m-d H:i:s')];return [$s,$source,$transport,$run];
 }
 private function options():array{return ['version'=>'shop2-research-run-v1','max_opportunities'=>2,'freshness_days'=>30,'per_task_ceiling'=>'0.020000','currency'=>'USD'];}
 private function quote(ResearchExecution $s,array $source,array $run):void {$c=$this->checked($s->plan('personalized_pod',$source['hash'],$run));$this->checked((new MonetaryReservationRepository())->reviewQuote('personalized_pod',json_encode(['provider'=>'openai','quote_id'=>'synthetic-'.wp_generate_uuid4(),'model'=>$c['model'],'request_sha256'=>$c['request_sha256'],'currency'=>'USD','maximum_charge'=>'0.020000','inclusive_all_charges'=>true,'valid_from'=>gmdate('Y-m-d\TH:i:s\Z',time()-10),'valid_until'=>gmdate('Y-m-d\TH:i:s\Z',time()+3600),'evidence_kind'=>'SYNTHETIC_TEST_ONLY']),'CONFIRM_PROVIDER_QUOTE'));}
 private function enqueue(ResearchExecution $s,array $source,array $run,string $key=''):array{return $this->checked($s->enqueue('personalized_pod',[$source['hash']],$this->options(),$run,$key?:'request-'.wp_generate_uuid4()));}
 public function testDurableBackgroundPollStrictIntakeThreeConceptsAndHumanSelection():void {
  [$s,$source,$transport,$run]=$this->boot();$this->quote($s,$source,$run);$j=$this->enqueue($s,$source,$run);self::assertSame('QUEUED',$j['state']);self::assertSame(0,$transport->starts());$waiting=$this->checked($s->step('personalized_pod',$j['id'],$j['event_sha256']));self::assertSame('WAITING',$waiting['state']);self::assertSame(1,$transport->starts());self::assertGreaterThan(0,$waiting['usage_id']);
  $done=$this->checked($s->step('personalized_pod',$j['id'],$waiting['event_sha256']));self::assertSame('AWAITING_REVIEW',$done['state']);self::assertSame(1,$transport->polls());self::assertCount(1,$done['results']);$repo=new CommercialResearchRepository();$v=$this->checked($repo->read('personalized_pod',$done['results'][0]['result_sha256']));self::assertSame('CONCEPTS_READY',$v['record']['stage']);self::assertCount(3,$v['record']['response']['concepts']);self::assertSame('ai_import',$v['record']['provenance']['method']);self::assertStringContainsString('SIMULATED',$v['record']['provenance']['provider']);self::assertSame($source['record']['research'],$v['record']['research']);$selected=$this->checked($repo->select('personalized_pod',$v['hash'],1));self::assertStringContainsString('DESIGN PROMPT',$selected['record']['design_prompt']);self::assertWPError($s->step('personalized_pod',$j['id'],$waiting['event_sha256']));self::assertSame(1,$transport->starts());self::assertTrue(DigiForge\Core\Settings::safety_locked());
 }
 public function testSourceFreshnessQuantityDuplicatesAndIdempotentIntent():void {
  [$s,$source,$t,$run]=$this->boot();$j=$this->enqueue($s,$source,$run,'exact-intent');self::assertSame($j['id'],$this->enqueue($s,$source,$run,'exact-intent')['id']);self::assertWPError($s->enqueue('personalized_pod',[$source['hash'],$source['hash']],$this->options(),$run,'duplicate'));$opts=$this->options();$opts['freshness_days']=1;self::assertWPError($s->enqueue('personalized_pod',[$source['hash']],$opts,$run,'stale'));$opts=$this->options();$opts['max_opportunities']=0;self::assertWPError($s->enqueue('personalized_pod',[$source['hash']],$opts,$run,'zero'));self::assertSame(0,$t->starts());
 }
