 public function testNetworkDefaultStopsBeforeReservationSecretOrHttpAccess():void {
  [$s,$source,$t,$run]=$this->boot();$s=new ResearchExecution();$j=$this->enqueue($s,$source,$run);$calls=0;$http=static function()use(&$calls){$calls++;return new WP_Error('offline_only');};add_filter('pre_http_request',$http,PHP_INT_MAX);try{self::assertWPError($s->step('personalized_pod',$j['id'],$j['event_sha256']));self::assertSame(0,$calls);self::assertSame(0,$this->checked($s->read('personalized_pod',$j['id']))['usage_id']);}finally{remove_filter('pre_http_request',$http,PHP_INT_MAX);}
 }
 public function testRewoundHeadCannotHideLaterDurableEvents():void {
  [$s,$source,$t,$run]=$this->boot();$this->quote($s,$source,$run);$j=$this->enqueue($s,$source,$run);global $wpdb;$name='df_s2_research_head_'.$j['id'];$old=$wpdb->get_var($wpdb->prepare('SELECT option_value FROM '.$wpdb->options.' WHERE option_name=%s',$name));$waiting=$this->checked($s->step('personalized_pod',$j['id'],$j['event_sha256']));self::assertSame('WAITING',$waiting['state']);$current=$wpdb->get_var($wpdb->prepare('SELECT option_value FROM '.$wpdb->options.' WHERE option_name=%s',$name));
  try{$wpdb->update($wpdb->options,['option_value'=>$old],['option_name'=>$name]);self::assertWPError($s->read('personalized_pod',$j['id']),'A valid old head cannot hide surviving newer events.');}finally{$wpdb->update($wpdb->options,['option_value'=>$current],['option_name'=>$name]);}
 }
