 }

 public function testInterruptedPersistenceKeepsRecoveryLeaseAndExpiresToUnknown():void {
  [$s,$source,$t,$run]=$this->boot();$this->quote($s,$source,$run);$j=$this->enqueue($s,$source,$run);$fault=static fn($q)=>str_contains($q,'INSERT INTO')&&str_contains($q,'df_s2_research_event_')&&str_contains($q,'DISPATCHING')?'SELECT missing_research_dispatch_ack':$q;add_filter('query',$fault);try{self::assertWPError($s->step('personalized_pod',$j['id'],$j['event_sha256']));}finally{remove_filter('query',$fault);}
  $v=$this->checked($s->read('personalized_pod',$j['id']));self::assertSame('RESERVED',$v['state']);global $wpdb;$row=$wpdb->get_row($wpdb->prepare('SELECT state,locked_by,lease_expires_at FROM '.DigiForge\Database\Tables::jobs().' WHERE id=%d',$j['id']),ARRAY_A);self::assertSame('RUNNING',$row['state']);self::assertNotNull($row['lease_expires_at'],'A failed active step must retain its expiry, not strand an unrecoverable RUNNING root.');self::assertWPError($s->recover('personalized_pod',$j['id'],$v['event_sha256']));$wpdb->update(DigiForge\Database\Tables::jobs(),['lease_expires_at'=>gmdate('Y-m-d H:i:s',time()-10)],['id'=>$j['id']]);$recovered=$this->checked($s->recover('personalized_pod',$j['id'],$v['event_sha256']));self::assertSame('UNKNOWN',$recovered['state']);self::assertWPError($s->step('personalized_pod',$j['id'],$recovered['event_sha256']));self::assertSame(0,$t->starts());
 }

