  $transport=new OfflineResearchTransport($response);$s=new ResearchExecution($transport);$this->quote($s,$source,$run);$j=$this->enqueue($s,$source,$run);$waiting=$this->checked($s->step('personalized_pod',$j['id'],$j['event_sha256']));self::assertWPError($s->step('personalized_pod',$j['id'],$waiting['event_sha256']));$held=$this->checked($s->read('personalized_pod',$j['id']));self::assertSame('UNKNOWN',$held['state']);self::assertSame([],$held['results']);self::assertSame(1,$transport->starts());self::assertSame(1,$transport->polls());
 }
