  try{self::assertSame(1,$wpdb->insert($wpdb->options,['option_name'=>$probe,'option_value'=>'uncommitted','autoload'=>'no']));self::assertWPError($s->step('personalized_pod',$j['id'],$j['event_sha256']));self::assertSame('1',(string)$wpdb->get_var('SELECT @@session.in_transaction'));self::assertNull($other->get_var($other->prepare('SELECT option_value FROM '.$other->options.' WHERE option_name=%s',$probe)));self::assertSame(0,$t->starts());}finally{$wpdb->query('ROLLBACK');$other->close();}
 }
 public function testCostEvidenceSeparatesSyntheticUsageActualChargeAndRetainedHold():void {
